-- Purpose: the `transcricoes` table for Demo 1 (audio to minutes). Run once on your Postgres
-- database before the first upload. No sample data here.
--
-- The workflow touches this table twice:
--   INSERT INTO transcricoes (transcricao, resumo) VALUES ($1, $2) RETURNING id
--   SELECT transcricao FROM transcricoes WHERE id = $1
-- So `id` must be generated by the database, and both text columns are written together.

CREATE TABLE IF NOT EXISTS transcricoes (
  id           BIGSERIAL PRIMARY KEY,
  transcricao  TEXT,                        -- full verbatim text returned by speech-to-text
  resumo       TEXT,                        -- executive summary; NULL when mode = arquivo
  criado_em    TIMESTAMPTZ DEFAULT now()
);

-- The download webhook looks rows up by primary key only, so no extra index is needed.
